/**
 * TMDB API Cloudflare Worker 反向代理 + /web 转发记录面板
 * =====================================================
 * 反向代理 api.themoviedb.org，供中国大陆无法直连的客户端（Rex / fw 等）使用。
 *
 * 额外功能：
 *   - 通过 KV（命名空间名 TMDB_LOG）记录被转发过的剧集（tv 详情 / tv 搜索），去重保存
 *   - 访问 /web 打开网页面板，以 TMDB 海报网格展示转发记录
 *
 * 参考：MoviePilot 官方文档的 TMDB Worker 反代实现（jxxghp/MoviePilot-Wiki）
 *
 * 传 Key 方式：
 *   1) 客户端自带 api_key（默认推荐，Worker 无需配置）
 *   2) 选做：Worker 环境变量 TMDB_API_KEY 自动注入（仅当客户端不方便带 Key 时）
 *
 * 部署：需先在 Cloudflare 创建 KV 命名空间并命名为 TMDB_LOG，绑定到本 Worker。
 * 未配置 KV 时 Worker 照常反代，仅 /web 面板显示“未配置 KV”。
 */

const TMDB_BASE = "https://api.themoviedb.org";
const IMG_BASE = "https://image.tmdb.org/t/p/w300";
const KV_KEY = "shows";
const MAX_RECORDS = 300;
// 内嵌的影视推荐站（site.html），访问 / 时返回。由构建脚本注入，勿手改。
const SITE_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\">\n    <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n    <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n    <title>CineTrack Platinum</title>\n    <link rel=\"preconnect\" href=\"https://api.themoviedb.org\">\n    <link rel=\"preconnect\" href=\"https://image.tmdb.org\">\n    <link rel=\"preconnect\" href=\"https://api.trakt.tv\">\n    <link rel=\"dns-prefetch\" href=\"https://cdn.tailwindcss.com\">\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        :root {\n            --anim-speed: 0.5s;\n            --ease-out: cubic-bezier(0.25, 0.46, 0.45, 0.94);\n            --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);\n        }\n        /* --- 核心升级：液态玻璃变量 --- */\n        .theme-dark {\n            --bg-color: #0f0c29; --text-main: #ffffff; --text-sub: rgba(255, 255, 255, 0.6);\n            /* 暗黑模式：极低透明度 + 高饱和度背景 = 液态感 */\n            --glass-bg: rgba(20, 20, 35, 0.45); \n            --glass-border: rgba(255, 255, 255, 0.12);\n            --glass-highlight: rgba(255, 255, 255, 0.15); /* 边缘高光 */\n            --glass-shadow: 0 20px 50px rgba(0, 0, 0, 0.6);\n            --btn-bg: rgba(255, 255, 255, 0.1); --input-bg: rgba(255, 255, 255, 0.08);\n            --card-bg: rgba(255, 255, 255, 0.05);\n            --header-bg: #0f0c29; --overlay-bg: #0f0c29;\n        }\n        .theme-light {\n            --bg-color: #f2f2f7; --text-main: #000000; --text-sub: rgba(0, 0, 0, 0.6);\n            /* 白天模式：像冰块一样的通透感 */\n            --glass-bg: rgba(255, 255, 255, 0.55); \n            --glass-border: rgba(255, 255, 255, 0.4);\n            --glass-highlight: rgba(255, 255, 255, 0.8);\n            --glass-shadow: 0 15px 40px rgba(0, 0, 0, 0.15);\n            --btn-bg: rgba(0, 0, 0, 0.05); --input-bg: rgba(0, 0, 0, 0.05);\n            --card-bg: rgba(0, 0, 0, 0.05);\n            --header-bg: #f2f2f7; --overlay-bg: #f2f2f7;\n        }\n\n        html, body { margin: 0; padding: 0; min-height: 100dvh; color: var(--text-main); background-color: var(--bg-color); transition: background-color 0.5s ease, color 0.5s ease; overscroll-behavior: none; -webkit-touch-callout: none; -webkit-user-select: none; user-select: none; touch-action: pan-x pan-y; padding-top: env(safe-area-inset-top); font-family: system-ui, -apple-system, BlinkMacSystemFont, sans-serif; overflow-x: hidden; -webkit-tap-highlight-color: transparent; }\n        img { pointer-events: none; -webkit-user-drag: none; }\n        /* 所有页面(含详情/各 overlay)统一禁用缩放、双击放大、右键、长按选择 */\n        .app-overlay, .app-overlay *, #search-overlay, #search-overlay *, #video-player-modal, #video-player-modal *, #login-modal, #login-modal * {\n            touch-action: pan-x pan-y;\n            -webkit-touch-callout: none;\n            -webkit-user-select: none;\n            user-select: none;\n        }\n        .hide-scroll::-webkit-scrollbar { display: none; }\n        \n        /* 动态流动背景 (增强液态感) */\n        .theme-dark .spatial-bg { position: fixed; inset: 0; z-index: -1; background: linear-gradient(-45deg, #0f0c29, #302b63, #24243e, #141e30); background-size: 400% 400%; animation: gradientFlow 15s ease infinite; opacity: 1; pointer-events: none; }\n        .theme-light .spatial-bg { position: fixed; inset: 0; z-index: -1; background: #f2f2f7; opacity: 1; pointer-events: none; }\n        @keyframes gradientFlow { 0% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } 100% { background-position: 0% 50%; } }\n        \n        header { position: relative; z-index: 500; }\n        .user-avatar-btn, #theme-btn, #magic-btn { width: 36px; height: 36px; border-radius: 50%; overflow: hidden; background: var(--btn-bg); border: 1px solid var(--glass-border); display: flex; align-items: center; justify-content: center; transition: transform 0.2s; cursor: pointer; color: var(--text-main); }\n        .user-avatar-btn:active, #theme-btn:active, #magic-btn:active { transform: scale(0.92); }\n        .status-dot { position: absolute; bottom: 2px; right: 2px; width: 8px; height: 8px; background: #4ade80; border-radius: 50%; border: 1.5px solid var(--bg-color); display: none; }\n        .user-avatar-btn.logged-in .status-dot { display: block; }\n        .type-toggle { display: flex; background: var(--btn-bg); backdrop-filter: blur(20px); border-radius: 100px; padding: 3px; border: 1px solid var(--glass-border); }\n        .toggle-btn { padding: 4px 14px; border-radius: 20px; font-size: 11px; font-weight: 700; color: var(--text-sub); transition: all 0.3s var(--ease-spring); }\n        .toggle-btn.active { background: var(--text-main); color: var(--bg-color); box-shadow: 0 2px 8px rgba(0,0,0,0.1); }\n        #search-trigger { flex: 1; height: 36px; margin: 0 8px; background: var(--input-bg); border-radius: 20px; display: flex; align-items: center; justify-content: center; gap: 6px; font-size: 13px; color: var(--text-sub); border: 1px solid var(--glass-border); backdrop-filter: blur(10px); cursor: pointer; transition: 0.2s; }\n        #search-trigger:active { opacity: 0.8; background: var(--glass-border); }\n        #main-container { transition: transform 0.5s var(--ease-out), opacity 0.5s ease; transform-origin: center 30vh; }\n        body.detail-open #main-container { transform: scale(0.95) translateX(-5%); opacity: 0.5; pointer-events: none; }\n        \n        .app-overlay { position: fixed; inset: 0; background: var(--overlay-bg); overflow-y: auto; overflow-x: hidden; opacity: 0; pointer-events: none; visibility: hidden; transform: translateX(100%); transition: transform var(--anim-speed) var(--ease-out), opacity 0.3s ease, visibility 0s 0.5s; box-shadow: -10px 0 30px rgba(0,0,0,0.3); }\n        .app-overlay.active { opacity: 1; pointer-events: auto; visibility: visible; transform: translateX(0); transition: transform var(--anim-speed) var(--ease-out), opacity 0.3s ease, visibility 0s; }\n        .app-overlay.dragging { transition: none !important; }\n        \n        #rec-overlay, #stats-overlay { z-index: 300; } \n        #detail-overlay { z-index: 350; } \n        #search-overlay { z-index: 600; }\n        #list-select-overlay { z-index: 450; background: var(--overlay-bg) !important; transform: translateX(100%); transition: transform 0.3s var(--ease-out), opacity 0.3s; }\n        #list-select-overlay.active { transform: translateX(0); }\n        \n        #video-player-modal { z-index: 500; position: fixed; inset: 0; background: #000; display: flex; align-items: center; justify-content: center; opacity: 0; pointer-events: none; transition: opacity 0.3s, transform 0.3s; transform: scale(0.9); }\n        #video-player-modal.active { opacity: 1; pointer-events: auto; transform: scale(1); }\n        .close-video-btn { position: absolute; top: calc(20px + env(safe-area-inset-top)); right: 20px; z-index: 510; width: 40px; height: 40px; border-radius: 50%; background: rgba(255,255,255,0.2); display: flex; align-items: center; justify-content: center; color: #fff; }\n        \n        .detail-top-bar { position: fixed; top: 0; left: 0; width: 100%; height: calc(64px + env(safe-area-inset-top)); background-color: var(--header-bg); z-index: 355; transition: background-color 0.5s ease; border-bottom: 1px solid var(--glass-border); }\n        #detail-container { padding-top: calc(64px + env(safe-area-inset-top)); }\n        .video-background { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; pointer-events: none; z-index: 0; opacity: 0; transition: opacity 1.5s ease; transform: scale(1.3); }\n        .video-background.playing { opacity: 0.6; }\n        .detail-hero-wrapper { opacity: 0; transition: opacity 0.5s 0.2s ease; } .app-overlay.active .detail-hero-wrapper { opacity: 1; }\n        .detail-content { transform: translateY(20px); opacity: 0; transition: all 0.5s 0.3s var(--ease-out); } .app-overlay.active .detail-content { transform: translateY(0); opacity: 1; }\n        .overlay-nav-btn { position: fixed; top: calc(12px + env(safe-area-inset-top)); width: 36px; height: 36px; border-radius: 50%; background: rgba(0,0,0,0.3); backdrop-filter: blur(20px); display: flex; align-items: center; justify-content: center; border: 1px solid rgba(255,255,255,0.1); opacity: 0; transform: scale(0.5); transition: all 0.4s 0.3s var(--ease-spring); z-index: 360; color: #fff; }\n        .app-overlay.active .overlay-nav-btn { opacity: 1; transform: scale(1); }\n        .btn-right { right: 20px; } .btn-left { left: 20px; } \n        .fs-btn { position: absolute; bottom: 20px; right: 20px; z-index: 50; width: 44px; height: 44px; border-radius: 50%; background: rgba(0,0,0,0.6); border: 1px solid rgba(255,255,255,0.3); backdrop-filter: blur(8px); display: flex; align-items: center; justify-content: center; color: white; transition: 0.2s; opacity: 0; transform: scale(0.8); }\n        .detail-hero-wrapper:hover .fs-btn, .video-background.playing ~ .fs-btn { opacity: 1; transform: scale(1); }\n        \n        .stats-grid { display: grid; grid-cols-2 gap-3; margin-top: 10px; }\n        .stat-card { background: var(--card-bg); padding: 15px; border-radius: 16px; border: 1px solid var(--glass-border); text-align: center; }\n        .stat-value { font-size: 20px; font-weight: 800; color: var(--text-main); margin-bottom: 2px; }\n        .stat-label { font-size: 11px; color: var(--text-sub); text-transform: uppercase; letter-spacing: 1px; }\n        .h-list-section { margin-top: 24px; padding-left: 20px; }\n        .h-list-title { font-size: 13px; font-weight: 700; color: var(--text-sub); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 12px; display: flex; align-items: center; gap: 6px; cursor: pointer; }\n        .h-list-scroll { display: flex; gap: 10px; overflow-x: auto; padding-right: 20px; padding-bottom: 10px; }\n        .h-card { width: 95px; flex-shrink: 0; display:flex; flex-direction:column; }\n        .h-card-img { aspect-ratio: 2/3; border-radius: 10px; overflow: hidden; background: var(--card-bg); margin-bottom: 4px; position: relative; }\n        .h-card-img img { width: 100%; height: 100%; object-fit: cover; }\n        .h-card-meta { display:flex; flex-direction:column; gap:1px; }\n        .h-card-title { font-size: 10px; color: var(--text-main); font-weight:700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n        .h-card-subtitle { font-size: 9px; color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace; letter-spacing: -0.3px; }\n        \n        .manager-card { position: relative; aspect-ratio: 2/3; border-radius: 10px; overflow: hidden; background: var(--card-bg); }\n        .manager-card img { width: 100%; height: 100%; object-fit: cover; }\n        .manager-overlay { position: absolute; bottom: 0; left: 0; width: 100%; background: linear-gradient(to top, rgba(0,0,0,0.95), rgba(0,0,0,0.6), transparent); padding: 24px 6px 6px; pointer-events: none; }\n        .manager-title { font-size: 11px; font-weight: 700; color: #fff; line-height: 1.2; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; text-shadow: 0 1px 2px black; }\n        .manager-subtitle { font-size: 9px; color: rgba(255,255,255,0.7); margin-top: 2px; font-family: ui-monospace, monospace; }\n        \n        .list-card { width: 140px; aspect-ratio: 16/9; border-radius: 12px; background: var(--btn-bg); border: 1px solid var(--glass-border); flex-shrink: 0; display: flex; flex-direction: column; justify-content: center; align-items: center; padding: 10px; text-align: center; cursor: pointer; transition: 0.2s; }\n        .list-card:active { transform: scale(0.95); background: var(--card-bg); }\n        .list-count { font-size: 20px; font-weight: 800; color: var(--text-main); }\n        .list-name { font-size: 11px; color: var(--text-sub); margin-top: 4px; line-clamp: 2; }\n        .item-delete-btn { position: absolute; top: 4px; right: 4px; width: 28px; height: 28px; border-radius: 50%; background: rgba(220, 38, 38, 0.95); display: flex; align-items: center; justify-content: center; color: white; z-index: 10; box-shadow: 0 4px 10px rgba(0,0,0,0.4); border: 1px solid rgba(255,255,255,0.3); }\n        .item-delete-btn:active { transform: scale(0.9); }\n        \n        .list-select-content { \n            padding-top: calc(64px + env(safe-area-inset-top));\n            padding-bottom: 24px;\n            max-height: 100vh; overflow-y: auto; \n        }\n        .select-item { \n            padding: 20px; border-bottom: 1px solid var(--glass-border); \n            font-weight: 600; font-size: 16px; color: var(--text-main); \n            display: flex; justify-content: space-between; align-items: center; \n        }\n        .select-item:active { background: var(--btn-bg); }\n        \n        .provider-list { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px; }\n        .provider-icon { width: 40px; height: 40px; border-radius: 10px; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); flex-shrink: 0; }\n        \n        /* === ⚠️ 关键修改：原生 iOS 液态玻璃 Docker === */\n        .nav-capsule { \n            position: fixed; \n            bottom: calc(4px + env(safe-area-inset-bottom)); \n            left: 50%; \n            transform: translateX(-50%); \n            height: 64px; \n            \n            /* 液态玻璃核心属性 */\n            background: var(--glass-bg); \n            /* 重点：高模糊 + 高饱和度 (saturate 200% 是原生感的关键) */\n            backdrop-filter: blur(35px) saturate(220%); \n            -webkit-backdrop-filter: blur(35px) saturate(220%);\n            \n            /* 模拟物理玻璃切割边缘 */\n            border-radius: 100px; \n            box-shadow: \n                var(--glass-shadow), \n                inset 0 0.5px 0 0 var(--glass-highlight), /* 顶部高光 */\n                inset 0 0 0 1px var(--glass-border); /* 极细内边框 */\n            \n            display: flex; \n            align-items: center; \n            justify-content: center; \n            padding: 5px; \n            z-index: 100; \n            width: auto; \n            min-width: 170px; \n            max-width: calc(100vw - 32px); \n            transition: all 0.6s var(--ease-spring); \n        }\n\n        .nav-inner { display: flex; align-items: center; gap: 4px; height: 100%; position: relative; overflow: hidden; }\n        \n        .nav-btn { height: 52px; border-radius: 40px; font-size: 15px; font-weight: 700; color: var(--text-sub); display: flex; align-items: center; justify-content: center; transition: all 0.4s ease; white-space: nowrap; position: relative; z-index: 2; }\n        \n        /* 选中态优化：悬浮感 */\n        .nav-btn.active { \n            background: var(--text-main); \n            color: var(--bg-color); \n            box-shadow: 0 4px 15px rgba(0,0,0,0.15); \n        }\n        .theme-dark .nav-btn.active { \n            background: #fff; \n            color: #000; \n            box-shadow: 0 4px 20px rgba(99, 102, 241, 0.4); \n        }\n        \n        .theme-dark .nav-btn.active span.text { background: linear-gradient(135deg, #2563eb, #9333ea); -webkit-background-clip: text; -webkit-text-fill-color: transparent; display: inline-block; }\n        .theme-light .nav-btn.active { background: #000; color: #fff; }\n        \n        #btn-trend, #btn-chart { width: 84px; } #btn-trend .icon-only { display: none; }\n        .v-divider { width: 1px; height: 18px; background: var(--text-sub); opacity: 0.2; margin: 0 4px; transition: 0.3s; }\n        .provider-group { display: flex; max-width: 0; opacity: 0; overflow: hidden; transition: all 0.5s var(--ease-quart); align-items: center; gap: 8px; }\n        \n        body.mode-charts .nav-capsule { width: calc(100vw - 32px); justify-content: space-between; padding: 5px 8px; }\n        body.mode-charts #btn-chart { width: 0; padding: 0; opacity: 0; margin: 0; }\n        body.mode-charts #btn-trend { width: 52px; height: 52px; border-radius: 50%; background: var(--btn-bg); color: var(--text-main); box-shadow: none; }\n        body.mode-charts #btn-trend span.text { display: none; }\n        body.mode-charts #btn-trend .icon-only { display: block; font-size: 22px; }\n        body.mode-charts .v-divider { width: 0; margin: 0; opacity: 0; }\n        body.mode-charts .provider-group { max-width: 300px; opacity: 1; flex: 1; justify-content: flex-end; padding-right: 2px; }\n        \n        .provider-btn { width: 44px; height: 44px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 800; opacity: 0.5; transform: scale(0.9); transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1); flex-shrink: 0; border: 2px solid transparent; }\n        body.mode-charts .provider-btn.active { opacity: 1; transform: scale(1.1); border-color: var(--text-main); z-index: 10; box-shadow: 0 8px 20px rgba(0,0,0,0.2); }\n        \n        .back-to-top { position: fixed; bottom: 100px; right: 20px; width: 44px; height: 44px; border-radius: 50%; background: var(--btn-bg); backdrop-filter: blur(10px); border: 1px solid var(--glass-border); color: var(--text-main); display: flex; align-items: center; justify-content: center; z-index: 90; opacity: 0; pointer-events: none; transform: translateY(20px); transition: all 0.4s var(--ease-spring); box-shadow: 0 10px 20px rgba(0,0,0,0.1); }\n        .back-to-top.show { opacity: 1; pointer-events: auto; transform: translateY(0); }\n        #search-overlay { position: fixed; inset: 0; z-index: 600; background: var(--bg-color); opacity: 0; pointer-events: none; transition: opacity 0.3s; padding-top: calc(20px + env(safe-area-inset-top)); }\n        .theme-dark #search-overlay { background: rgba(0,0,0,0.9); backdrop-filter: blur(30px); }\n        .theme-light #search-overlay { background: rgba(255,255,255,0.9); backdrop-filter: blur(30px); }\n        #search-overlay.active { opacity: 1; pointer-events: auto; }\n        #search-input { width: 100%; background: transparent; border: none; outline: none; color: var(--text-main); font-size: 20px; font-weight: 600; padding: 20px; border-bottom: 1px solid var(--glass-border); }\n        .login-modal { position: fixed; inset: 0; z-index: 500; background: rgba(0,0,0,0.8); backdrop-filter: blur(20px); display: flex; align-items: center; justify-content: center; opacity: 0; pointer-events: none; transition: opacity 0.3s; }\n        .login-modal.active { opacity: 1; pointer-events: auto; }\n        .login-card { background: #1c1c1e; width: 85%; max-width: 320px; border-radius: 24px; padding: 24px; text-align: center; border: 1px solid rgba(255,255,255,0.1); color: #fff; }\n        #toast { position: fixed; top: 12px; left: 50%; transform: translateX(-50%) translateY(-100px); background: var(--text-main); backdrop-filter: blur(20px); color: var(--bg-color); padding: 12px 24px; border-radius: 100px; font-weight: 600; font-size: 14px; box-shadow: 0 10px 40px rgba(0,0,0,0.3); z-index: 600; transition: transform 0.5s var(--ease-spring); display: flex; align-items: center; gap: 8px; }\n        #toast.show { transform: translateX(-50%) translateY(0); }\n        .grid-item-title { position: absolute; bottom: 0; width: 100%; background: linear-gradient(to top, rgba(0,0,0,0.8), transparent); color: #fff; font-size: 10px; padding: 4px; text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n        .rec-grid { display: grid; grid-cols-3 sm:grid-cols-5 gap-3; padding: 0 20px; }\n        .rec-card { aspect-ratio: 2/3; border-radius: 12px; overflow: hidden; position: relative; background: var(--card-bg); transition: all 0.5s cubic-bezier(0.34, 1.56, 0.64, 1); transform-style: preserve-3d; }\n        .rec-card.swapping { transform: rotateY(90deg) scale(0.8); opacity: 0; }\n        .rec-card img { width: 100%; height: 100%; object-fit: cover; }\n        .rec-section-title { font-size: 13px; font-weight: 700; color: var(--text-sub); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 12px; display: flex; align-items: center; gap: 8px; padding: 0 20px; }\n        /* 长列表渲染性能：跳过视口外海报的布局/绘制 */\n        #grid > * { content-visibility: auto; contain-intrinsic-size: 190px; }\n        @media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; } }\n    </style>\n</head>\n<body>\n    <div class=\"spatial-bg\"></div>\n    <div id=\"toast\"><svg class=\"w-5 h-5 text-green-500\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 13l4 4L19 7\"></path></svg><span id=\"toast-msg\">Success</span></div>\n\n    <div id=\"main-container\">\n        <header class=\"px-5 pt-6 pb-2 flex justify-between items-center relative gap-2\">\n            <div id=\"user-btn\" class=\"user-avatar-btn flex-shrink-0\" onclick=\"Trakt.handleUserClick()\"><svg fill=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z\"/></svg><div class=\"status-dot\"></div></div>\n            <div id=\"theme-btn\" onclick=\"Theme.toggle()\"></div>\n            <div id=\"magic-btn\" onclick=\"Recs.open()\"><svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z\"></path></svg></div>\n            <div id=\"hist-btn\" class=\"user-avatar-btn flex-shrink-0\" onclick=\"location.href='/web'\" title=\"反代历史：查看浏览过的剧\"><svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z\"></path></svg></div>\n            <div id=\"search-trigger\" onclick=\"Search.open()\"><svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z\"/></svg><span>Search...</span></div>\n            <div class=\"type-toggle flex-shrink-0\"><button onclick=\"setType('movie')\" id=\"t-movie\" class=\"toggle-btn active\">Movie</button><button onclick=\"setType('tv')\" id=\"t-tv\" class=\"toggle-btn\">TV</button></div>\n        </header>\n        <main class=\"px-2 pt-2 pb-36\">\n            <div id=\"grid\" class=\"grid grid-cols-3 sm:grid-cols-4 gap-2\"></div>\n            <div id=\"loading\" class=\"py-12 flex justify-center opacity-0 transition-opacity\"><div class=\"w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin\"></div></div>\n        </main>\n    </div>\n\n    <div id=\"rec-overlay\" class=\"app-overlay hide-scroll\">\n        <button onclick=\"Recs.close()\" class=\"overlay-nav-btn btn-right\"><svg class=\"w-5 h-5 text-white\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6 18L18 6M6 6l12 12\"></path></svg></button>\n        <div id=\"rec-content-container\">\n            <div id=\"rec-header-area\"><div><h2 class=\"rec-title\">今天看什么</h2><div class=\"text-[10px] opacity-50\">Based on your history</div></div><button onclick=\"Recs.refreshAll()\" class=\"w-9 h-9 rounded-full bg-white/10 flex items-center justify-center border border-white/10 active:scale-90 transition-transform\"><svg class=\"w-4 h-4 text-white\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15\"></path></svg></button></div>\n            <div id=\"rec-auth-msg\" class=\"hidden flex-col items-center justify-center h-64 text-center\"><p class=\"opacity-60 mb-4\">请先登录 Trakt 获取个性化推荐</p><button onclick=\"Trakt.startDeviceFlow()\" class=\"px-6 py-2 bg-[#ed1c24] rounded-full font-bold text-sm text-white\">去登录</button></div>\n            <div id=\"rec-list\" class=\"pb-32\"><div class=\"rec-section-title\"><span class=\"w-2 h-2 rounded-full bg-yellow-500\"></span> Movies</div><div id=\"rec-grid-movie\" class=\"rec-grid mb-8\"></div><div class=\"rec-section-title\"><span class=\"w-2 h-2 rounded-full bg-blue-500\"></span> TV Shows</div><div id=\"rec-grid-tv\" class=\"rec-grid\"></div></div>\n        </div>\n    </div>\n\n    <div id=\"stats-overlay\" class=\"app-overlay hide-scroll\"><button onclick=\"Stats.close()\" class=\"overlay-nav-btn btn-right\"><svg class=\"w-5 h-5 text-white\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6 18L18 6M6 6l12 12\"></path></svg></button><div id=\"stats-content\" class=\"min-h-screen relative p-6 pt-24 text-main\"></div></div>\n\n    <div id=\"list-select-overlay\" class=\"app-overlay hide-scroll\">\n        <div class=\"detail-top-bar\"></div>\n        <button onclick=\"Trakt.closeListModal()\" class=\"overlay-nav-btn btn-right\"><svg class=\"w-5 h-5 text-white\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6 18L18 6M6 6l12 12\"></path></svg></button>\n        <div class=\"list-select-content\">\n            <div class=\"text-xl font-bold mb-4 px-4\" style=\"color:var(--text-main)\">添加到片单</div>\n            <div id=\"user-lists-container\"></div>\n        </div>\n    </div>\n\n    <div id=\"search-overlay\"><div class=\"flex items-center px-2\"><input type=\"text\" id=\"search-input\" placeholder=\"搜索...\" autocomplete=\"off\"><button onclick=\"Search.close()\" class=\"px-4 py-2 opacity-60 font-bold text-sm\">取消</button></div><div id=\"search-results\" class=\"p-2 grid grid-cols-3 gap-2 overflow-y-auto h-[calc(100vh-80px)] pb-20\"></div></div>\n\n    <div id=\"detail-overlay\" class=\"app-overlay hide-scroll\"><div class=\"detail-top-bar\"></div><button onclick=\"goBack()\" id=\"btn-back\" class=\"overlay-nav-btn btn-left\"><svg class=\"w-5 h-5 text-white\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 19l-7-7 7-7\"></path></svg></button><button onclick=\"closeDetail()\" id=\"btn-close\" class=\"overlay-nav-btn btn-right\"><svg class=\"w-5 h-5 text-white\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6 18L18 6M6 6l12 12\"></path></svg></button><div id=\"detail-container\" class=\"min-h-screen relative pb-20\"></div></div>\n\n    <div id=\"video-player-modal\"><button onclick=\"closeVideoModal()\" class=\"close-video-btn\"><svg class=\"w-6 h-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6 18L18 6M6 6l12 12\"></path></svg></button><div id=\"video-container\" class=\"w-full aspect-video max-w-4xl bg-black\"></div></div>\n\n    <div id=\"login-modal\" class=\"login-modal\"><div class=\"login-card\"><h2 class=\"text-xl font-bold mb-2\">Trakt 登录</h2><p class=\"text-white/60 text-sm mb-4\">请访问 trakt.tv/activate 并输入代码</p><div id=\"device-code\" class=\"text-3xl font-mono font-bold text-[#ed1c24] bg-white/5 p-4 rounded-lg my-4 tracking-widest\">....</div><button onclick=\"Trakt.closeModal()\" class=\"w-full bg-white/10 py-3 rounded-xl font-bold text-sm text-white\">取消</button></div></div>\n\n    <button id=\"back-to-top\" class=\"back-to-top\" onclick=\"scrollToTop()\"><svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M5 10l7-7m0 0l7 7m-7-7v18\"></path></svg></button>\n\n    <nav class=\"nav-capsule\"><div class=\"nav-inner\"><button onclick=\"setMode('trending')\" id=\"btn-trend\" class=\"nav-btn active\"><span class=\"text\">热门</span><svg class=\"icon-only w-6 h-6\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17.657 18.657A8 8 0 016.343 7.343S7 9 9 10c0-2 .5-5 2.986-7C14 5 16.09 5.777 17.656 7.343A7.975 7.975 0 0120 13a7.975 7.975 0 01-2.343 5.657z\"></path><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9.879 16.121A3 3 0 1012.015 11L11 14H9c0 .768.293 1.536.879 2.121z\"></path></svg></button><div class=\"v-divider\"></div><button onclick=\"setMode('charts')\" id=\"btn-chart\" class=\"nav-btn\"><span class=\"text\">榜单</span></button><div id=\"provider-group\" class=\"provider-group\"></div></div></nav>\n\n    <script>\n        const API_KEY = 'd913a144d0ba98fdca978f53a1ce27a5';\n        const BASE_URL = '/3'; // 由 tmdb-proxy Worker 托管时，TMDB 请求走本 Worker(同源，自动记录反代历史且大陆可用)；若单独部署到别处，改为你的反代域名如 https://tmdb.example.com/3\n        const IMG_URL = 'https://image.tmdb.org/t/p/w500';\n        const CARD_URL = 'https://image.tmdb.org/t/p/w342';\n        const ORIG_IMG_URL = 'https://image.tmdb.org/t/p/original';\n        const TRAKT_CLIENT_ID = '95b59922670c84040db3632c7aac6f33704f6ffe5cbf3113a056e37cb45cb482';\n        const TRAKT_CLIENT_SECRET = '5982b1e599762223af2afeed0294437284db8220aba1d70ff94df98fad2e9a93'; \n        const TRAKT_API_URL = 'https://api.trakt.tv';\n\n        let state = { type: 'movie', mode: 'trending', provider: 'netflix', page: 1, loading: false, loadedIds: new Set() };\n        let historyStack = []; \n        let currentView = null; \n        let currentAddId = null; \n        let currentAddType = null;\n\n        // 全站禁用：两指缩放(pinch)、双击放大、右键菜单、长按选择（含详情页/所有 overlay）\n        (function(){\n            document.addEventListener('contextmenu', e => e.preventDefault());\n            document.addEventListener('gesturestart', e => e.preventDefault());\n            document.addEventListener('gesturechange', e => e.preventDefault());\n            document.addEventListener('gestureend', e => e.preventDefault());\n            document.addEventListener('touchmove', e => { if(e.touches.length > 1) e.preventDefault(); }, {passive:false});\n        })();\n\n        const PROVIDERS = [\n            { id: 'netflix', name: 'N', color: '#E50914', pid: 8 },\n            { id: 'disney', name: 'D+', color: '#0063e5', pid: 337 },\n            { id: 'apple', name: 'TV+', color: '#ffffff', pid: 350 },\n            { id: 'hbo', name: 'Max', color: '#4d1bf5', pid: 1899 },\n            { id: 'chinese', name: '国', color: '#D4000F', pid: 'zh' }\n        ];\n\n        const Theme = {\n            current: localStorage.getItem('theme') || 'system',\n            icons: {\n                light: '<svg class=\"w-5 h-5 text-yellow-500\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"></path></svg>',\n                dark: '<svg class=\"w-5 h-5 text-blue-400\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"></path></svg>',\n                system: '<svg class=\"w-5 h-5 text-gray-400\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z\"></path></svg>'\n            },\n            init() {\n                this.apply(this.current);\n                window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', e => { if(this.current === 'system') this.apply('system'); });\n            },\n            toggle() {\n                const modes = ['system', 'light', 'dark'];\n                let idx = modes.indexOf(this.current);\n                this.current = modes[(idx + 1) % modes.length];\n                localStorage.setItem('theme', this.current);\n                this.apply(this.current);\n                showToast(`Theme: ${this.current.charAt(0).toUpperCase() + this.current.slice(1)}`);\n            },\n            apply(mode) {\n                const root = document.documentElement;\n                const btn = document.getElementById('theme-btn');\n                let isDark = false;\n                if (mode === 'system') isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;\n                else isDark = (mode === 'dark');\n                if (isDark) { root.classList.add('theme-dark'); root.classList.remove('theme-light'); } \n                else { root.classList.add('theme-light'); root.classList.remove('theme-dark'); }\n                if(btn) btn.innerHTML = this.icons[mode];\n            }\n        };\n\n        function formatDate(isoString) {\n            if(!isoString) return '';\n            const d = new Date(isoString);\n            const mon = String(d.getMonth() + 1).padStart(2, '0');\n            const day = String(d.getDate()).padStart(2, '0');\n            const hr = String(d.getHours()).padStart(2, '0');\n            const min = String(d.getMinutes()).padStart(2, '0');\n            return `${mon}.${day}-${hr}.${min}`;\n        }\n\n        const SwipeHandler = {\n            startX: 0, startY: 0, currentOverlay: null, threshold: 0,\n            init() {\n                document.addEventListener('touchstart', e => this.start(e), {passive: true});\n                document.addEventListener('touchmove', e => this.move(e), {passive: false});\n                document.addEventListener('touchend', e => this.end(e), {passive: true});\n                this.threshold = window.innerWidth * 0.4;\n            },\n            start(e) {\n                this.startX = e.touches[0].screenX;\n                this.startY = e.touches[0].screenY;\n                if(document.getElementById('video-player-modal').classList.contains('active')) return;\n                if(document.getElementById('list-select-overlay').classList.contains('active')) this.currentOverlay = document.getElementById('list-select-overlay');\n                else if(document.getElementById('detail-overlay').classList.contains('active')) this.currentOverlay = document.getElementById('detail-overlay');\n                else if(document.getElementById('rec-overlay').classList.contains('active')) this.currentOverlay = document.getElementById('rec-overlay');\n                else if(document.getElementById('stats-overlay').classList.contains('active')) this.currentOverlay = document.getElementById('stats-overlay');\n                else this.currentOverlay = null;\n                if(this.currentOverlay) {\n                    const target = e.target;\n                    const scrollable = target.closest('.overflow-x-auto, .h-list-scroll');\n                    if(scrollable && scrollable.scrollLeft > 0) this.currentOverlay = null;\n                }\n            },\n            move(e) {\n                if(!this.currentOverlay) return;\n                const diffX = e.touches[0].screenX - this.startX;\n                const diffY = e.touches[0].screenY - this.startY;\n                if(diffX > 0 && Math.abs(diffX) > Math.abs(diffY)) {\n                    if(e.cancelable) e.preventDefault();\n                    this.currentOverlay.classList.add('dragging');\n                    this.currentOverlay.style.transform = `translateX(${diffX}px)`;\n                }\n            },\n            end(e) {\n                if(!this.currentOverlay) return;\n                const diffX = e.changedTouches[0].screenX - this.startX;\n                this.currentOverlay.classList.remove('dragging');\n                this.currentOverlay.style.transform = '';\n                if(diffX > this.threshold) {\n                    if(this.currentOverlay.id === 'list-select-overlay') Trakt.closeListModal();\n                    else if(this.currentOverlay.id === 'detail-overlay') goBack();\n                    else if(this.currentOverlay.id === 'rec-overlay') Recs.close();\n                    else if(this.currentOverlay.id === 'stats-overlay') Stats.close();\n                } \n                this.currentOverlay = null;\n            }\n        };\n\n        const Stats = {\n            async open() {\n                if(!Trakt.token) { Trakt.startDeviceFlow(); return; }\n                const ol = document.getElementById('stats-overlay');\n                ol.classList.add('active');\n                document.body.classList.add('detail-open');\n                const container = document.getElementById('stats-content');\n                container.innerHTML = '<div class=\"text-center mt-20 opacity-50\">正在加载数据...</div>';\n                try {\n                    const [profile, stats, lists] = await Promise.all([\n                        fetch(`${TRAKT_API_URL}/users/me?extended=full`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${Trakt.token}` } }).then(r=>{if(r.status===401) throw '401'; return r.json()}),\n                        fetch(`${TRAKT_API_URL}/users/me/stats`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${Trakt.token}` } }).then(r=>r.json()),\n                        fetch(`${TRAKT_API_URL}/users/me/lists`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${Trakt.token}` } }).then(r=>r.json())\n                    ]);\n                    const fallback = `https://ui-avatars.com/api/?name=${profile.username}&background=random&color=fff&size=128`;\n                    const avatarSrc = profile.images?.avatar?.full || fallback;\n                    container.innerHTML = `<div id=\"stats-main-view\"><div class=\"flex flex-col items-center mb-8\"><div class=\"w-24 h-24 rounded-full overflow-hidden border-2 border-white/20 mb-4 shadow-xl\"><img src=\"${avatarSrc}\" onerror=\"this.src='${fallback}'\" class=\"w-full h-full object-cover\"></div><h2 class=\"text-2xl font-bold\" style=\"color:var(--text-main)\">${profile.username}</h2><p class=\"text-sm opacity-50\" style=\"color:var(--text-sub)\">加入于 ${new Date(profile.joined_at).getFullYear()}</p></div><div class=\"px-2\"><h3 class=\"text-xs font-bold mb-3 uppercase tracking-widest opacity-40\">观影生涯</h3><div class=\"stats-grid\"><div class=\"stat-card\"><div class=\"stat-value text-yellow-400\">${Math.floor(stats.movies.minutes / 60)}h</div><div class=\"stat-label\">电影时长</div></div><div class=\"stat-card\"><div class=\"stat-value text-blue-400\">${stats.movies.watched}</div><div class=\"stat-label\">看过电影</div></div><div class=\"stat-card\"><div class=\"stat-value text-green-400\">${Math.floor(stats.episodes.minutes / 60)}h</div><div class=\"stat-label\">剧集时长</div></div><div class=\"stat-card\"><div class=\"stat-value text-purple-400\">${stats.episodes.watched}</div><div class=\"stat-label\">看过集数</div></div></div></div><div id=\"stats-lists-container\" class=\"mt-8\"><div class=\"text-center opacity-50 text-xs py-4\">正在同步片单...</div></div><div class=\"mt-12 px-4 pb-12\"><button onclick=\"Trakt.logout(); Stats.close()\" class=\"w-full py-4 rounded-xl bg-white/10 border border-white/10 text-red-400 font-bold active:scale-95 transition-transform\">退出登录</button></div></div>`;\n                    this.loadListsData(lists);\n                } catch(e) { \n                    if(e === '401') { Trakt.logout(); Stats.close(); return; }\n                    container.innerHTML = '<div class=\"text-center mt-20 opacity-50\">加载失败，请检查网络</div>'; \n                }\n            },\n            async loadListsData(customLists) {\n                const container = document.getElementById('stats-lists-container');\n                if(!container) return;\n                try {\n                    const [history, watchlist] = await Promise.all([\n                        fetch(`${TRAKT_API_URL}/users/me/history?limit=10`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${Trakt.token}` } }).then(r=>r.json()),\n                        fetch(`${TRAKT_API_URL}/users/me/watchlist?limit=10&sort=added,desc`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${Trakt.token}` } }).then(r=>r.json())\n                    ]);\n                    const resolveImages = async (items) => {\n                        const results = [];\n                        for(const item of items) {\n                            let type = item.type;\n                            let tmdbId, displayTitle, displaySubtitle;\n                            let dateStr = formatDate(item.watched_at || item.listed_at);\n                            if (type === 'episode') { tmdbId = item.show.ids.tmdb; type = 'tv'; displaySubtitle = `S${String(item.episode.season).padStart(2,'0')}-E${String(item.episode.number).padStart(2,'0')} / ${dateStr}`; displayTitle = item.show.title; } \n                            else { type = type === 'show' ? 'tv' : 'movie'; tmdbId = item[type === 'tv' ? 'show' : 'movie'].ids.tmdb; displaySubtitle = dateStr; displayTitle = item.movie ? item.movie.title : item.show.title; }\n                            if(!tmdbId) continue;\n                            try {\n                                const res = await fetch(`${BASE_URL}/${type}/${tmdbId}?api_key=${API_KEY}&language=zh-CN`);\n                                const data = await res.json();\n                                if(data.poster_path) results.push({ id: tmdbId, type: type, poster: CARD_URL+data.poster_path, title: data.title || data.name, subtitle: displaySubtitle });\n                            } catch(e){}\n                        }\n                        return results;\n                    };\n                    const [histItems, watchItems] = await Promise.all([resolveImages(history), resolveImages(watchlist)]);\n                    let html = '';\n                    if(histItems.length > 0) html += `<div class=\"h-list-section\"><h4 class=\"h-list-title\" onclick=\"Stats.openListDetail('history', '最近观看')\">最近观看 <span class=\"text-xs opacity-50 ml-2 text-blue-400\">点击管理 ></span></h4><div class=\"h-list-scroll hide-scroll\">${histItems.map(i => `<div class=\"h-card\" onclick=\"openDetail(${i.id}, '${i.poster.replace(CARD_URL,'')}', '', '${i.type}', true)\"><div class=\"h-card-img\"><img src=\"${i.poster}\" loading=\"lazy\" decoding=\"async\" alt=\"\"></div><div class=\"h-card-meta\"><div class=\"h-card-title\">${i.title}</div><div class=\"h-card-subtitle\">${i.subtitle}</div></div></div>`).join('')}</div></div>`;\n                    if(watchItems.length > 0) html += `<div class=\"h-list-section\"><h4 class=\"h-list-title\" onclick=\"Stats.openListDetail('watchlist', '待看清单')\">待看清单 <span class=\"text-xs opacity-50 ml-2 text-blue-400\">点击管理 ></span></h4><div class=\"h-list-scroll hide-scroll\">${watchItems.map(i => `<div class=\"h-card\" onclick=\"openDetail(${i.id}, '${i.poster.replace(CARD_URL,'')}', '', '${i.type}', true)\"><div class=\"h-card-img\"><img src=\"${i.poster}\" loading=\"lazy\" decoding=\"async\" alt=\"\"></div><div class=\"h-card-meta\"><div class=\"h-card-title\">${i.title}</div><div class=\"h-card-subtitle\">${i.subtitle}</div></div></div>`).join('')}</div></div>`;\n                    if(customLists.length > 0) html += `<div class=\"h-list-section\"><h4 class=\"h-list-title\">我的片单</h4><div class=\"h-list-scroll hide-scroll\">${customLists.map(l => `<div class=\"list-card\" onclick=\"Stats.openListDetail('${l.ids.trakt}', '${l.name.replace(/'/g, \"\\\\'\")}')\"><div class=\"list-count\">${l.item_count}</div><div class=\"list-name\">${l.name}</div></div>`).join('')}</div></div>`;\n                    container.innerHTML = html;\n                } catch(e) { console.error(e); }\n            },\n            async openListDetail(listId, listName) {\n                const container = document.getElementById('stats-content');\n                document.getElementById('stats-main-view').style.display = 'none';\n                const detailId = `list-detail-${listId}`;\n                let detailEl = document.getElementById(detailId);\n                if(!detailEl) { detailEl = document.createElement('div'); detailEl.id = detailId; container.appendChild(detailEl); }\n                detailEl.style.display = 'block';\n                detailEl.innerHTML = `<div class=\"flex items-center mb-6\"><button onclick=\"Stats.closeListDetail('${listId}')\" class=\"mr-4 p-2 bg-white/10 rounded-full\"><svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M15 19l-7-7 7-7\"/></svg></button><h2 class=\"text-xl font-bold truncate\" style=\"color:var(--text-main)\">${listName}</h2></div><div id=\"list-grid-${listId}\" class=\"grid grid-cols-3 gap-3\">Loading...</div>`;\n                try {\n                    let url = '';\n                    if(listId === 'watchlist') url = `${TRAKT_API_URL}/users/me/watchlist?extended=full&sort=added,desc`;\n                    else if(listId === 'history') url = `${TRAKT_API_URL}/users/me/history?extended=full&limit=100`;\n                    else url = `${TRAKT_API_URL}/users/me/lists/${listId}/items?extended=full`;\n                    const res = await fetch(url, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${Trakt.token}` } });\n                    const items = await res.json();\n                    const gridEl = document.getElementById(`list-grid-${listId}`);\n                    gridEl.innerHTML = '';\n                    if(items.length === 0) gridEl.innerHTML = '<div class=\"col-span-3 text-center opacity-50 py-10\">空空如也</div>';\n                    for(const item of items) {\n                        let type = item.type; let tmdbId, traktId, displaySubtitle;\n                        let dateStr = formatDate(item.watched_at || item.listed_at);\n                        if (type === 'episode') { tmdbId = item.show.ids.tmdb; traktId = item.episode.ids.trakt; type = 'tv'; displaySubtitle = `S${String(item.episode.season).padStart(2,'0')}-E${String(item.episode.number).padStart(2,'0')} / ${dateStr}`; } \n                        else { type = type === 'show' ? 'tv' : 'movie'; tmdbId = item[type === 'tv' ? 'show' : 'movie'].ids.tmdb; traktId = item[type === 'tv' ? 'show' : 'movie'].ids.trakt; displaySubtitle = dateStr; }\n                        if(!tmdbId) continue;\n                        const itemEl = document.createElement('div');\n                        itemEl.className = 'manager-card relative';\n                        itemEl.innerHTML = `<div class=\"item-delete-btn\" onclick=\"event.stopPropagation(); Trakt.removeFromList('${listId}', '${item.type}', ${traktId}, this.parentElement)\"><svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16\"></path></svg></div><img src=\"\" class=\"opacity-50 transition-opacity duration-500\"><div class=\"manager-overlay\"><div class=\"manager-title\">...</div><div class=\"manager-subtitle\">${displaySubtitle}</div></div>`;\n                        itemEl.onclick = () => openDetail(tmdbId, '', '', type, true);\n                        gridEl.appendChild(itemEl);\n                        fetch(`${BASE_URL}/${type}/${tmdbId}?api_key=${API_KEY}&language=zh-CN`).then(r=>r.json()).then(d=>{ if(d.poster_path) itemEl.querySelector('img').src = CARD_URL + d.poster_path; itemEl.querySelector('.manager-title').innerText = d.title || d.name; itemEl.querySelector('img').classList.remove('opacity-50'); });\n                    }\n                } catch(e) { document.getElementById(`list-grid-${listId}`).innerHTML = 'Load failed'; }\n            },\n            closeListDetail(listId) { const detailEl = document.getElementById(`list-detail-${listId}`); if(detailEl) detailEl.remove(); document.getElementById('stats-main-view').style.display = 'block'; },\n            close() { document.getElementById('stats-overlay').classList.remove('active'); const container = document.getElementById('stats-content'); container.innerHTML = ''; if(!document.getElementById('detail-overlay').classList.contains('active') && !document.getElementById('rec-overlay').classList.contains('active')) { document.body.classList.remove('detail-open'); } }\n        };\n\n        const Trakt = {\n            token: localStorage.getItem('trakt_token'),\n            init() { if(this.token) this.loadProfile(); },\n            handleUserClick() { \n                if (this.token) Stats.open();\n                else this.startDeviceFlow(); \n            },\n            logout() {\n                this.token = null; localStorage.removeItem('trakt_token');\n                const btn = document.getElementById('user-btn'); btn.classList.remove('logged-in');\n                btn.innerHTML = '<svg fill=\"currentColor\" viewBox=\"0 0 24 24\"><path d=\"M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z\"/></svg><div class=\"status-dot\"></div>';\n                showToast('已退出');\n            },\n            async startDeviceFlow() {\n                document.getElementById('login-modal').classList.add('active');\n                const res = await fetch(`${TRAKT_API_URL}/oauth/device/code`, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({client_id: TRAKT_CLIENT_ID}) });\n                const data = await res.json();\n                document.getElementById('device-code').innerText = data.user_code;\n                this.pollInterval = setInterval(async () => {\n                    const pollRes = await fetch(`${TRAKT_API_URL}/oauth/device/token`, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({ code: data.device_code, client_id: TRAKT_CLIENT_ID, client_secret: TRAKT_CLIENT_SECRET }) });\n                    if(pollRes.status === 200) {\n                        const tData = await pollRes.json();\n                        this.token = tData.access_token; localStorage.setItem('trakt_token', this.token);\n                        clearInterval(this.pollInterval); this.closeModal(); this.loadProfile();\n                        showToast('登录成功');\n                        if(document.getElementById('rec-overlay').classList.contains('active')) Recs.open();\n                    }\n                }, data.interval * 1000);\n            },\n            closeModal() { document.getElementById('login-modal').classList.remove('active'); if(this.pollInterval) clearInterval(this.pollInterval); },\n            async loadProfile() {\n                try {\n                    const res = await fetch(`${TRAKT_API_URL}/users/me?extended=full`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${this.token}` } });\n                    if(res.ok) {\n                        const u = await res.json();\n                        const fallback = `https://ui-avatars.com/api/?name=${u.username}&background=random&color=fff&bold=true`;\n                        const src = u.images?.avatar?.full || fallback;\n                        document.getElementById('user-btn').classList.add('logged-in');\n                        document.getElementById('user-btn').innerHTML = `<img src=\"${src}\" onerror=\"this.src='${fallback}'\"><div class=\"status-dot\"></div>`;\n                    }\n                } catch(e){}\n            },\n            async addToWatchlist(id, type) { this.sync('/sync/watchlist', this.buildBody(id, type), '已加入待看'); },\n            async markWatched(id, type) { this.sync('/sync/history', this.buildBody(id, type), '已标记已看'); },\n            async openAddToListModal(id, type) {\n                if(!this.token) { this.startDeviceFlow(); return; }\n                currentAddId = id; currentAddType = type;\n                const modal = document.getElementById('list-select-overlay');\n                modal.classList.add('active');\n                const container = document.getElementById('user-lists-container');\n                container.innerHTML = '<div class=\"p-4 text-center opacity-50\">获取列表中...</div>';\n                try {\n                    const res = await fetch(`${TRAKT_API_URL}/users/me/lists`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${this.token}` } });\n                    const lists = await res.json();\n                    container.innerHTML = lists.map(l => `<div class=\"select-item\" onclick=\"Trakt.addToList('${l.ids.trakt}', '${l.name}')\"><span>${l.name}</span><span class=\"opacity-50 text-xs\">${l.item_count} items</span></div>`).join('');\n                } catch(e) { container.innerHTML = '获取失败'; }\n            },\n            closeListModal() { document.getElementById('list-select-overlay').classList.remove('active'); },\n            async addToList(listId, listName) {\n                this.closeListModal();\n                const body = this.buildBody(currentAddId, currentAddType);\n                try {\n                    await fetch(`${TRAKT_API_URL}/users/me/lists/${listId}/items`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${this.token}` }, body: JSON.stringify(body) });\n                    showToast(`已加入 ${listName}`);\n                } catch(e) { showToast('添加失败'); }\n            },\n            async removeFromList(listId, type, traktId, elToRemove) {\n                if(!confirm('确定从片单移除?')) return;\n                let body = {};\n                if (type === 'episode') body = { episodes: [{ ids: { trakt: traktId } }] };\n                else if (type === 'show') body = { shows: [{ ids: { trakt: traktId } }] };\n                else body = { movies: [{ ids: { trakt: traktId } }] };\n                let endpoint = '';\n                if(listId === 'watchlist') endpoint = '/sync/watchlist/remove';\n                else if(listId === 'history') endpoint = '/sync/history/remove';\n                else endpoint = `/users/me/lists/${listId}/items/remove`;\n                try {\n                    const res = await fetch(`${TRAKT_API_URL}${endpoint}`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${this.token}` }, body: JSON.stringify(body) });\n                    if(res.ok) { elToRemove.style.transform = 'scale(0)'; setTimeout(() => elToRemove.remove(), 300); showToast('已移除'); } else { throw 'err'; }\n                } catch(e) { showToast('移除失败'); }\n            },\n            buildBody(id, type) { return type === 'movie' ? { movies: [{ ids: { tmdb: id } }] } : { shows: [{ ids: { tmdb: id } }] }; },\n            async sync(endpoint, body, successMsg) {\n                try {\n                    const res = await fetch(`${TRAKT_API_URL}${endpoint}`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${this.token}` }, body: JSON.stringify(body) });\n                    if(res.ok) showToast(successMsg);\n                } catch(e) { showToast('操作失败'); }\n            }\n        };\n\n        const Recs = {\n            pool: { movie: [], tv: [] }, displayed: { movie: [], tv: [] },\n            open() {\n                const ol = document.getElementById('rec-overlay'); ol.classList.add('active'); document.body.classList.add('detail-open'); \n                if(!Trakt.token) { document.getElementById('rec-auth-msg').classList.remove('hidden'); document.getElementById('rec-auth-msg').classList.add('flex'); document.getElementById('rec-list').classList.add('hidden'); } \n                else { document.getElementById('rec-auth-msg').classList.add('hidden'); document.getElementById('rec-auth-msg').classList.remove('flex'); document.getElementById('rec-list').classList.remove('hidden'); if(this.pool.movie.length === 0) this.initData(); }\n            },\n            close() { document.getElementById('rec-overlay').classList.remove('active'); if(!document.getElementById('detail-overlay').classList.contains('active')){ document.body.classList.remove('detail-open'); } },\n            async initData() { showToast('正在生成推荐...'); await Promise.all([this.fetchPool('movies'), this.fetchPool('shows')]); this.refreshAll(false); },\n            async fetchPool(typeStr) { try { const res = await fetch(`${TRAKT_API_URL}/recommendations/${typeStr}?limit=50&ignore_collected=true`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${Trakt.token}` } }); const data = await res.json(); this.pool[typeStr === 'movies' ? 'movie' : 'tv'] = data.map(item => ({ id: item.ids.tmdb, title: item.title, type: typeStr === 'movies' ? 'movie' : 'tv' })); } catch(e) {} },\n            async refreshAll(animation = true) { if(animation) { document.querySelectorAll('.rec-card').forEach(c => c.classList.add('swapping')); await new Promise(r => setTimeout(r, 300)); } await Promise.all([this.fillSection('movie'), this.fillSection('tv')]); },\n            async fillSection(type) { const source = this.pool[type]; if(source.length < 5) return; const shuffled = [...source].sort(() => 0.5 - Math.random()); const picks = shuffled.slice(0, 5); this.displayed[type] = picks; const htmls = await Promise.all(picks.map((item, idx) => this.renderCard(item, idx))); document.getElementById(`rec-grid-${type}`).innerHTML = htmls.join(''); },\n            async replaceOne(type, idx, btnEl) { const card = btnEl.closest('.rec-card'); card.classList.add('swapping'); const currentIds = this.displayed[type].map(i => i.id); const candidates = this.pool[type].filter(i => !currentIds.includes(i.id)); if(candidates.length === 0) { showToast('没更多推荐了'); card.classList.remove('swapping'); return; } const newItem = candidates[Math.floor(Math.random() * candidates.length)]; this.displayed[type][idx] = newItem; setTimeout(async () => { const newHtml = await this.renderCard(newItem, idx); card.outerHTML = newHtml; }, 300); },\n            async renderCard(item, idx) { let img = ''; try { const res = await fetch(`${BASE_URL}/${item.type}/${item.id}?api_key=${API_KEY}&language=zh-CN`); const data = await res.json(); if(data.poster_path) img = CARD_URL + data.poster_path; } catch(e) {} if(!img) return ''; return `<div class=\"rec-card\" onclick=\"openDetail(${item.id}, '${img.replace(CARD_URL,'')}', '', '${item.type}')\"><img src=\"${img}\" class=\"animate-fade-in\" loading=\"lazy\" decoding=\"async\" alt=\"\"><div class=\"mini-refresh-btn\" onclick=\"event.stopPropagation(); Recs.replaceOne('${item.type}', ${idx}, this)\"><svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15\"></path></svg></div></div>`; }\n        };\n\n        const Search = {\n            timer: null,\n            open() { document.getElementById('search-overlay').classList.add('active'); document.getElementById('search-input').focus(); },\n            close() { document.getElementById('search-overlay').classList.remove('active'); document.getElementById('search-input').value = ''; document.getElementById('search-results').innerHTML = ''; },\n            init() { document.getElementById('search-input').addEventListener('input', (e) => { clearTimeout(this.timer); if(e.target.value.length > 1) this.timer = setTimeout(() => this.execute(e.target.value), 500); }); },\n            async execute(query) {\n                const res = await fetch(`${BASE_URL}/search/multi?api_key=${API_KEY}&language=zh-CN&query=${query}`);\n                const data = await res.json();\n                document.getElementById('search-results').innerHTML = data.results.map(item => {\n                    if(!item.poster_path && !item.profile_path) return '';\n                    const img = item.poster_path || item.profile_path;\n                    const type = item.media_type;\n                    if(type === 'person') return `<div class=\"aspect-[2/3] rounded-lg overflow-hidden bg-white/10 relative\" onclick=\"openActorDetail(${item.id}, '${item.name.replace(/'/g, \"\\\\'\")}', '${img}', true)\"><img src=\"${CARD_URL + img}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\" alt=\"\"><div class=\"absolute bottom-0 w-full bg-black/60 text-[10px] p-1 text-center truncate text-white\">${item.name}</div></div>`;\n                    else return `<div class=\"aspect-[2/3] rounded-lg overflow-hidden bg-white/10 relative\" onclick=\"openDetail(${item.id}, '${img}', '${item.backdrop_path}', '${type}', true)\"><img src=\"${CARD_URL + img}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\" alt=\"\"><div class=\"absolute bottom-0 w-full bg-black/60 text-[10px] p-1 text-center truncate text-white\">${item.title || item.name}</div></div>`;\n                }).join('');\n            }\n        };\n\n        window.onload = () => {\n            try {\n                Theme.init();\n                Trakt.init();\n                Search.init();\n                SwipeHandler.init();\n                renderProviders();\n                setTimeout(() => loadData(), 500);\n            } catch(e) { console.error('Init error', e); }\n            window.addEventListener('scroll', () => { \n                if ((window.innerHeight + window.scrollY) >= document.body.offsetHeight - 800) loadData();\n                const btn = document.getElementById('back-to-top');\n                if (window.scrollY > 500) btn.classList.add('show'); else btn.classList.remove('show');\n            });\n        };\n        \n        function scrollToTop() { window.scrollTo({ top: 0, behavior: 'smooth' }); }\n\n        async function openDetail(id, posterPath, backdropPath, typeOverride, pushToStack = true) {\n            if (pushToStack && currentView) historyStack.push(currentView);\n            currentView = { view: 'content', id, posterPath, backdropPath, typeOverride };\n            const overlay = document.getElementById('detail-overlay'); \n            const container = document.getElementById('detail-container');\n            const targetType = typeOverride || state.type;\n            const heroImage = (backdropPath && backdropPath !== 'null') ? (IMG_URL + backdropPath) : (IMG_URL + posterPath);\n            Search.close(); document.body.classList.add('detail-open'); overlay.scrollTop = 0; overlay.classList.add('active');\n            container.innerHTML = `<div class=\"detail-hero-wrapper w-full aspect-video bg-gray-900 relative overflow-hidden\"><img src=\"${heroImage}\" class=\"detail-hero-img absolute inset-0 w-full h-full object-cover opacity-60 blur-sm\"><div class=\"absolute inset-0 bg-gradient-to-t from-black/80 to-transparent\"></div></div><div class=\"px-5 pt-5 detail-content\"><div class=\"h-8 w-3/4 bg-white/10 rounded mb-4 animate-pulse\"></div></div>`;\n            try {\n                const [info, videos, credits, similar, providers] = await Promise.all([\n                    fetch(`${BASE_URL}/${targetType}/${id}?api_key=${API_KEY}&language=zh-CN`).then(r=>r.json()),\n                    fetch(`${BASE_URL}/${targetType}/${id}/videos?api_key=${API_KEY}`).then(r=>r.json()),\n                    fetch(`${BASE_URL}/${targetType}/${id}/credits?api_key=${API_KEY}&language=zh-CN`).then(r=>r.json()),\n                    fetch(`${BASE_URL}/${targetType}/${id}/recommendations?api_key=${API_KEY}&language=zh-CN`).then(r=>r.json()),\n                    fetch(`${BASE_URL}/${targetType}/${id}/watch/providers?api_key=${API_KEY}`).then(r=>r.json())\n                ]);\n                const finalBackdrop = info.backdrop_path ? (ORIG_IMG_URL + info.backdrop_path) : heroImage;\n                const hdImg = new Image(); hdImg.src = finalBackdrop;\n                hdImg.onload = () => { if(container.querySelector('.detail-hero-img')) container.querySelector('.detail-hero-img').src = finalBackdrop; };\n                const trailer = videos.results.find(v => v.type==='Trailer' && v.site==='YouTube');\n                let videoHtml = '';\n                if (trailer) { videoHtml = `<iframe src=\"https://www.youtube.com/embed/${trailer.key}?autoplay=1&mute=1&controls=0&loop=1&playlist=${trailer.key}&playsinline=1&modestbranding=1&rel=0\" class=\"video-background\" onload=\"this.classList.add('playing')\"></iframe><button class=\"fs-btn\" onclick=\"playFullscreenTrailer('${trailer.key}')\"><svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4\"></path></svg></button>`; }\n                const cnProviders = providers.results?.CN?.flatrate || providers.results?.US?.flatrate || [];\n                const providerHtml = cnProviders.length > 0 ? `<div class=\"mb-6\"><h3 class=\"text-xs font-bold mb-3 uppercase tracking-widest\" style=\"color:var(--text-sub)\">Where to Watch</h3><div class=\"provider-list\">${cnProviders.map(p => `<div class=\"provider-icon\"><img src=\"${CARD_URL + p.logo_path}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\" alt=\"\"></div>`).join('')}</div></div>` : '';\n                let seasonsHtml = '';\n                if(targetType === 'tv' && info.seasons) { seasonsHtml = `<div class=\"mb-8\"><h3 class=\"text-xs font-bold mb-4 uppercase tracking-widest\" style=\"color:var(--text-sub)\">分季 (Seasons)</h3><div class=\"flex gap-3 overflow-x-auto hide-scroll pb-2\">${info.seasons.filter(s => s.season_number > 0).map(s => `<div class=\"shrink-0 w-24 flex flex-col gap-2\" onclick=\"loadEpisodes(${id}, ${s.season_number})\"><div class=\"aspect-[2/3] rounded-lg overflow-hidden bg-white/10 relative\">${s.poster_path ? `<img src=\"${CARD_URL+s.poster_path}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\" alt=\"\">` : '<div class=\"w-full h-full flex items-center justify-center text-xs\">暂无</div>'}</div><span class=\"text-xs text-center opacity-70\" style=\"color:var(--text-main)\">${s.name}</span></div>`).join('')}</div><div id=\"episodes-area\" class=\"mt-4 space-y-3\"></div></div>`; }\n                const recHtml = similar.results.length > 0 ? `<div class=\"mb-8\"><h3 class=\"text-xs font-bold mb-4 uppercase tracking-widest\" style=\"color:var(--text-sub)\">猜你喜欢</h3><div class=\"flex gap-3 overflow-x-auto hide-scroll pb-2 -mx-5 px-5\">${similar.results.slice(0,10).map(m => `<div class=\"shrink-0 w-28 flex flex-col gap-2\" onclick=\"openDetail(${m.id}, '${m.poster_path}', '${m.backdrop_path}', '${targetType}', true)\"><div class=\"aspect-[2/3] rounded-lg overflow-hidden bg-white/10\"><img src=\"${CARD_URL+m.poster_path}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\" alt=\"\"></div><span class=\"text-[10px] text-center opacity-60 truncate\" style=\"color:var(--text-main)\">${m.title||m.name}</span></div>`).join('')}</div></div>` : '';\n                const trailerUrl = trailer ? `https://www.youtube.com/watch?v=${trailer.key}` : null;\n                const year = (info.release_date || info.first_air_date || '').split('-')[0];\n                container.innerHTML = `<div class=\"detail-hero-wrapper w-full aspect-video bg-gray-900 relative shrink-0 overflow-hidden\">${videoHtml}<img src=\"${finalBackdrop}\" class=\"detail-hero-img absolute inset-0 w-full h-full object-cover z-10 transition-opacity duration-1000 ${trailer ? 'opacity-0 delay-1000' : ''}\"><div class=\"absolute inset-0 bg-gradient-to-b from-black/30 via-transparent to-black z-20\"></div><div class=\"absolute bottom-0 left-0 w-full p-6 pb-2 bg-gradient-to-t from-black via-black/80 to-transparent z-20\"><h1 class=\"text-3xl font-extrabold text-white leading-tight mb-2 shadow-black drop-shadow-lg\">${info.title || info.name}</h1><div class=\"flex items-center gap-3 text-xs font-semibold text-white/60 uppercase tracking-wide\"><span class=\"bg-white/10 px-2 py-1 rounded text-white/90 border border-white/5\">${year}</span><span>${info.genres?.[0]?.name}</span><span class=\"text-yellow-500 flex items-center gap-1\">★ ${(info.vote_average).toFixed(1)}</span></div></div></div><div class=\"px-5 pt-5 pb-32 detail-content relative\"><a href=\"rex://tmdb?id=${id}&type=${targetType}\" onclick=\"event.stopPropagation()\" class=\"block w-full mb-6 py-4 rounded-2xl text-center font-extrabold text-base text-white active:scale-[0.97] transition-transform\" style=\"background:linear-gradient(135deg,#ed1c24,#ff7a45);box-shadow:0 10px 24px rgba(237,28,36,0.35)\">▶ 在 Rex 观看</a><div class=\"flex gap-3 mb-6\">${trailerUrl ? `<a href=\"${trailerUrl}\" target=\"_blank\" class=\"flex-1 bg-[var(--btn-bg)] text-[var(--text-main)] text-center py-3.5 rounded-xl font-bold text-sm shadow-lg flex items-center justify-center gap-2 border border-[var(--glass-border)]\">预告</a>` : `<div class=\"flex-1 bg-[var(--btn-bg)] opacity-30 text-center py-3.5 rounded-xl font-bold text-sm border border-[var(--glass-border)]\">暂无</div>`}<button onclick=\"Trakt.addToWatchlist(${id}, '${targetType}')\" class=\"w-14 bg-[var(--btn-bg)] rounded-xl flex items-center justify-center border border-[var(--glass-border)] active:scale-95 transition-transform text-[var(--text-main)]\"><svg class=\"w-6 h-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 6v6m0 0v6m0-6h6m-6 0H6\"></path></svg></button><button onclick=\"Trakt.markWatched(${id}, '${targetType}')\" class=\"w-14 bg-[var(--btn-bg)] rounded-xl flex items-center justify-center border border-[var(--glass-border)] active:scale-95 transition-transform text-green-400\"><svg class=\"w-6 h-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button><button onclick=\"Trakt.openAddToListModal(${id}, '${targetType}')\" class=\"w-14 bg-[var(--btn-bg)] rounded-xl flex items-center justify-center border border-[var(--glass-border)] active:scale-95 transition-transform text-blue-400\"><svg class=\"w-6 h-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4 6h16M4 10h16M4 14h16M4 18h16\"></path></svg></button></div>${providerHtml}<p class=\"text-[15px] leading-relaxed font-normal mb-8 opacity-80\" style=\"color:var(--text-main)\">${info.overview || '暂无简介'}</p>${seasonsHtml}<div class=\"mb-8\"><h3 class=\"text-xs font-bold mb-4 uppercase tracking-widest\" style=\"color:var(--text-sub)\">Cast</h3><div class=\"flex gap-4 overflow-x-auto hide-scroll pb-4 -mx-5 px-5\">${credits.cast.slice(0,8).map(c => `<div class=\"flex flex-col items-center w-16 shrink-0 gap-2\" onclick=\"openActorDetail(${c.id}, '${c.name.replace(/'/g, \"\\\\'\")}', '${c.profile_path}', true)\"><div class=\"w-14 h-14 rounded-full overflow-hidden bg-white/5 shadow-inner border border-white/5\"><img src=\"${c.profile_path ? CARD_URL+c.profile_path : 'https://ui-avatars.com/api/?name='+c.name}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\" alt=\"\"></div><span class=\"text-[10px] opacity-50 text-center truncate w-full\" style=\"color:var(--text-main)\">${c.name}</span></div>`).join('')}</div></div>${recHtml}</div>`;\n            } catch(e) { console.error(e); }\n        }\n\n        function playFullscreenTrailer(key) { document.getElementById('video-container').innerHTML = `<iframe width=\"100%\" height=\"100%\" src=\"https://www.youtube.com/embed/${key}?autoplay=1&rel=0&modestbranding=1\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>`; document.getElementById('video-player-modal').classList.add('active'); }\n        function closeVideoModal() { document.getElementById('video-container').innerHTML = ''; document.getElementById('video-player-modal').classList.remove('active'); }\n        async function openActorDetail(id, name, profilePath, pushToStack = true) { if (pushToStack && currentView) historyStack.push(currentView); currentView = { view: 'actor', id, name, profilePath }; const overlay = document.getElementById('detail-overlay'); const container = document.getElementById('detail-container'); Search.close(); document.body.classList.add('detail-open'); overlay.scrollTop = 0; overlay.classList.add('active'); const profileImg = profilePath && profilePath!=='null' ? IMG_URL+profilePath : `https://ui-avatars.com/api/?name=${name}`; container.innerHTML = `<div class=\"pt-24 px-6 flex flex-col items-center animate-pulse\"><div class=\"w-32 h-32 rounded-full bg-white/10 mb-4\"></div><div class=\"h-6 w-1/2 bg-white/10 rounded\"></div></div>`; try { const res = await fetch(`${BASE_URL}/person/${id}/combined_credits?api_key=${API_KEY}&language=zh-CN`); const data = await res.json(); const personRes = await fetch(`${BASE_URL}/person/${id}?api_key=${API_KEY}&language=zh-CN`); const personData = await personRes.json(); const works = data.cast.filter(i => i.poster_path).sort((a,b) => b.popularity - a.popularity); container.innerHTML = `<div class=\"pt-24 px-6 pb-8 flex flex-col items-center detail-content\"><div class=\"w-32 h-32 rounded-full overflow-hidden border-2 border-white/10 shadow-2xl mb-5\"><img src=\"${profileImg}\" class=\"w-full h-full object-cover\"></div><h2 class=\"text-2xl font-bold text-center mb-2\" style=\"color:var(--text-main)\">${name}</h2><p class=\"text-xs opacity-50 text-center line-clamp-3 max-w-sm leading-relaxed\" style=\"color:var(--text-main)\">${personData.biography || '暂无简介'}</p></div><div class=\"px-2 pb-32\"><h3 class=\"px-2 text-xs font-bold mb-4 uppercase tracking-widest\" style=\"color:var(--text-sub)\">Known For</h3><div class=\"grid grid-cols-3 sm:grid-cols-4 gap-2\">${works.map(item => `<div class=\"aspect-[2/3] rounded-lg overflow-hidden bg-white/10 relative\" onclick=\"openDetail(${item.id}, '${item.poster_path}', '${item.backdrop_path}', '${item.media_type}', true)\"><img src=\"${CARD_URL + item.poster_path}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\"></div>`).join('')}</div></div>`; } catch(e) {} }\n        function goBack() { if (historyStack.length > 0) { const prev = historyStack.pop(); if (prev.view === 'actor') openActorDetail(prev.id, prev.name, prev.profilePath, false); else openDetail(prev.id, prev.posterPath, prev.backdropPath, prev.typeOverride, false); } else { closeDetail(); } }\n        function closeDetail() { historyStack = []; currentView = null; document.getElementById('detail-overlay').classList.remove('active'); if(!document.getElementById('rec-overlay').classList.contains('active') && !document.getElementById('stats-overlay').classList.contains('active')) { document.body.classList.remove('detail-open'); } setTimeout(() => { document.getElementById('detail-container').innerHTML = ''; }, 800); }\n        async function loadEpisodes(tvId, seasonNum) { const area = document.getElementById('episodes-area'); area.innerHTML = '<div class=\"text-center py-4 opacity-50\">加载中...</div>'; try { const res = await fetch(`${BASE_URL}/tv/${tvId}/season/${seasonNum}?api_key=${API_KEY}&language=zh-CN`); const data = await res.json(); area.innerHTML = data.episodes.map(e => `<div class=\"flex gap-3 p-3 rounded-lg border border-[var(--glass-border)] bg-[var(--card-bg)]\"><div class=\"w-24 shrink-0 aspect-video rounded overflow-hidden bg-black\">${e.still_path ? `<img src=\"${CARD_URL+e.still_path}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\" alt=\"\">` : ''}</div><div class=\"flex-1 min-w-0 flex flex-col justify-center\"><div class=\"flex justify-between items-baseline mb-1\"><span class=\"text-sm font-bold truncate mr-2\" style=\"color:var(--text-main)\">${e.episode_number}. ${e.name}</span><span class=\"text-[10px] opacity-40\" style=\"color:var(--text-main)\">${e.air_date||''}</span></div><p class=\"text-[11px] opacity-60 line-clamp-2\" style=\"color:var(--text-main)\">${e.overview||'无简介'}</p></div></div>`).join(''); } catch(e) { area.innerHTML = '加载失败'; } }\n        function setType(t) { if(state.type===t) return; state.type=t; state.page=1; resetUI(); resetGrid(); }\n        function setMode(m) { if(state.mode===m) return; state.mode=m; state.page=1; const tB=document.getElementById('btn-trend'),cB=document.getElementById('btn-chart'); if(m==='charts'){ document.body.classList.add('mode-charts'); tB.classList.remove('active'); cB.classList.add('active'); } else { document.body.classList.remove('mode-charts'); tB.classList.add('active'); cB.classList.remove('active'); } resetGrid(); }\n        function setProvider(pid) { if(state.provider===pid) return; state.provider=pid; state.page=1; renderProviders(); resetGrid(); }\n        function resetUI() { document.getElementById('t-movie').className=state.type==='movie'?'toggle-btn active':'toggle-btn'; document.getElementById('t-tv').className=state.type==='tv'?'toggle-btn active':'toggle-btn'; }\n        function renderProviders() { document.getElementById('provider-group').innerHTML = PROVIDERS.map(p => `<button onclick=\"setProvider('${p.id}')\" class=\"provider-btn ${state.provider===p.id?'active':''}\" style=\"background:${p.color}; color:${p.color==='#ffffff'?'#000':'#fff'}\">${p.name}</button>`).join(''); }\n        function resetGrid() { document.getElementById('grid').innerHTML = ''; state.loadedIds.clear(); loadData(); }\n        function showToast(msg) { const el=document.getElementById('toast'); document.getElementById('toast-msg').innerText=msg; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),3000); }\n\n        async function loadData() {\n            if(state.loading) return; state.loading = true; if (state.page > 1) document.getElementById('loading').classList.remove('opacity-0');\n            try {\n                let items = [];\n                if(state.mode === 'trending') {\n                    try {\n                        const controller = new AbortController();\n                        const id = setTimeout(() => controller.abort(), 1500); \n                        const res = await fetch(`https://api.trakt.tv/${state.type === 'movie' ? 'movies' : 'shows'}/trending?page=${state.page}&limit=15`, { headers: { 'Content-Type': 'application/json', 'trakt-api-version': '2', 'trakt-api-key': TRAKT_CLIENT_ID, 'Authorization': `Bearer ${Trakt.token}` }, signal: controller.signal });\n                        clearTimeout(id);\n                        if(!res.ok) throw new Error('Trakt Error');\n                        const traktData = await res.json();\n                        items = await Promise.all(traktData.map(t => fetch(`${BASE_URL}/${state.type}/${(t.movie||t.show).ids.tmdb}?api_key=${API_KEY}&language=zh-CN`).then(r=>r.json()).catch(()=>null)));\n                    } catch(e) {\n                        const fallbackUrl = `${BASE_URL}/discover/${state.type}?api_key=${API_KEY}&language=zh-CN&sort_by=popularity.desc&page=${state.page}`;\n                        const fbRes = await fetch(fallbackUrl);\n                        items = (await fbRes.json()).results;\n                    }\n                } else {\n                    const provider = PROVIDERS.find(p => p.id === state.provider);\n                    const url = provider.id === 'chinese' ? `${BASE_URL}/discover/${state.type}?api_key=${API_KEY}&language=zh-CN&sort_by=popularity.desc&with_original_language=zh&page=${state.page}` : `${BASE_URL}/discover/${state.type}?api_key=${API_KEY}&language=zh-CN&sort_by=popularity.desc&with_watch_providers=${provider.pid}&watch_region=US&page=${state.page}`;\n                    const res = await fetch(url);\n                    items = (await res.json()).results;\n                }\n                const grid = document.getElementById('grid');\n                if(!items) items = [];\n                items.forEach((item, idx) => {\n                    if(!item || !item.poster_path) return;\n                    if (state.loadedIds.has(item.id)) return;\n                    state.loadedIds.add(item.id);\n                    const el = document.createElement('div');\n                    el.className = 'aspect-[2/3] rounded-xl overflow-hidden bg-white/10 opacity-0 transform translate-y-6 transition-all duration-700 cursor-pointer relative';\n                    el.style.transitionDelay = `${idx * 40}ms`;\n                    const targetType = state.type; \n                    el.onclick = () => openDetail(item.id, item.poster_path, item.backdrop_path, targetType);\n                    el.innerHTML = `<img src=\"${CARD_URL + item.poster_path}\" class=\"w-full h-full object-cover\" loading=\"lazy\" decoding=\"async\" alt=\"\"><div class=\"grid-item-title theme-light-only\">${item.title || item.name}</div>`;\n                    grid.appendChild(el);\n                    setTimeout(() => { el.classList.remove('opacity-0', 'translate-y-6'); }, 50);\n                });\n                state.page++;\n            } catch(e) { console.error(e); }\n            state.loading = false; document.getElementById('loading').classList.add('opacity-0');\n        }\n    </script>\n</body>\n</html>\n";

/** 首页：返回内嵌的影视推荐站 */
function serveSite() {
  return new Response(SITE_HTML, { headers: { "Content-Type": "text/html; charset=utf-8" } });
}

/** 北京时区当前时间字符串 YYYY-MM-DD HH:MM */
function nowStr() {
  return new Date().toLocaleString("zh-CN", { timeZone: "Asia/Shanghai", hour12: false }).replace("/", "-").replace("/", "-");
}

/** 从一次被转发的 TV 请求的响应 JSON 里提取剧集条目 */
function extractShows(data, path) {
  const out = [];
  if (path === "/3/search/tv") {
    const list = (data && data.results) || [];
    for (const r of list) {
      if (r && r.id) out.push({ id: r.id, title: r.name || r.original_name || "", poster_path: r.poster_path || "" });
    }
  } else if (/^\/3\/tv\/\d+/.test(path)) {
    if (data && data.id) out.push({ id: data.id, title: data.name || data.original_name || "", poster_path: data.poster_path || "" });
  }
  return out;
}

/** 合并新条目到 KV 记录（按 id 去重，更新最新名称/海报，保留首次时间），cap 上限 */
async function logShows(shows) {
  if (!shows.length) return;
  if (typeof TMDB_LOG === "undefined") return; // 未绑定 KV，仅反代不记录
  try {
    let list = (await TMDB_LOG.get(KV_KEY, "json")) || [];
    const byId = new Map(list.map((s) => [String(s.id), s]));
    for (const s of shows) {
      const key = String(s.id);
      const cur = byId.get(key);
      if (cur) {
        cur.title = s.title || cur.title;
        cur.poster_path = s.poster_path || cur.poster_path;
        cur.last_seen = nowStr();
      } else {
        byId.set(key, { id: s.id, title: s.title, poster_path: s.poster_path, added_at: nowStr(), last_seen: nowStr() });
      }
    }
    let arr = [...byId.values()];
    if (arr.length > MAX_RECORDS) arr = arr.slice(arr.length - MAX_RECORDS);
    await TMDB_LOG.put(KV_KEY, JSON.stringify(arr));
  } catch (e) {
    console.error("[log] fail:", e && e.message);
  }
}

/** /web 面板 HTML：海报网格展示转发过的剧集 */
async function servePanel() {
  let items = [];
  let kvBound = typeof TMDB_LOG !== "undefined";
  if (kvBound) {
    try { items = (await TMDB_LOG.get(KV_KEY, "json")) || []; } catch (e) { items = []; }
  }
  const rows = items
    .map((s) => `<div class="card">
      ${s.poster_path
        ? `<img src="${IMG_BASE}${s.poster_path}" alt="" onerror="this.replaceWith(document.createElement('span'))"/>`
        : `<span class="ph">无海报</span>`}
      <div class="t">${(s.title || "").replace(/[<>&]/g, "")}</div>
      <div class="m">加入 ${s.added_at || "-"}<br/>最近 ${s.last_seen || "-"}</div>
    </div>`)
    .join("");
  const html = `<!doctype html><html lang="zh"><head><meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>TMDB 反代 · 转发记录</title>
<style>
  *{box-sizing:border-box} body{margin:0;font-family:-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;background:#0f172a;color:#e2e8f0}
  .wrap{max-width:1100px;margin:0 auto;padding:20px}
  h1{font-size:20px} .sub{color:#94a3b8;font-size:13px;margin:4px 0 16px}
  .bar{display:flex;gap:10px;align-items:center;margin-bottom:16px}
  input{flex:1;padding:9px 12px;border-radius:8px;border:1px solid #334155;background:#1e293b;color:#e2e8f0;font-size:14px}
  .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:14px}
  .card{background:#1e293b;border:1px solid #334155;border-radius:10px;overflow:hidden}
  .card img{width:100%;aspect-ratio:2/3;object-fit:cover;display:block}
  .card .ph{display:flex;width:100%;aspect-ratio:2/3;align-items:center;justify-content:center;color:#64748b;background:#0b1220;font-size:12px}
  .card .t{padding:6px 8px;font-size:12px;line-height:1.3;min-height:34px}
  .card .m{padding:0 8px 8px;font-size:10px;color:#94a3b8}
  .empty{text-align:center;color:#94a3b8;padding:60px 0}
  .kv{display:inline-block;padding:3px 8px;border-radius:6px;font-size:11px;background:${kvBound ? "#14532d" : "#7f1d1d"};color:#bbf7d0;margin-left:8px}
</style></head><body><div class="wrap">
  <h1>TMDB 反代 · 转发记录 <span class="kv">${kvBound ? "KV 已连接" : "未配置 KV（仅反代不记录）"}</span></h1>
  <div class="sub">本面板记录经此 Worker 转发过的剧集（/3/tv 与 /3/search/tv），共 ${items.length} 条，去重、上限 ${MAX_RECORDS} 条。</div>
  <div class="bar"><input id="q" placeholder="按剧名筛选…" oninput="flt(this.value)"/><button onclick="location.reload()" style="padding:9px 14px;border-radius:8px;border:0;background:#2563eb;color:#fff;cursor:pointer">刷新</button></div>
  ${rows ? `<div class="grid" id="g">${rows}</div>` : `<div class="empty">暂无转发记录。用 Rex 打开任意剧集详情后再回来看看。</div>`}
</div>
<script>function flt(v){v=v.toLowerCase();document.querySelectorAll("#g .card").forEach(c=>{c.style.display=c.textContent.toLowerCase().includes(v)?"":"none";});}</script>
</body></html>`;
  return new Response(html, { headers: { "Content-Type": "text/html; charset=utf-8" } });
}

async function handleRequest(request) {
  const url = new URL(request.url);
  const path = url.pathname;

  // 首页：影视推荐站（yingshituijian）
  if (path === "/" || path === "/index.html") return serveSite();
  // /web 面板
  if (path === "/web" || path === "/web/") return servePanel();

  const params = url.searchParams;
  if (typeof TMDB_API_KEY !== "undefined" && TMDB_API_KEY && !params.has("api_key")) {
    params.set("api_key", TMDB_API_KEY);
  }

  const apiUrl = TMDB_BASE + path + "?" + params.toString();
  const headers = new Headers(request.headers);
  headers.set("Host", "api.themoviedb.org");
  headers.delete("origin");
  headers.delete("referer");

  let resp;
  try {
    resp = await fetch(apiUrl, {
      method: request.method,
      headers,
      body: ["GET", "HEAD"].includes(request.method) ? undefined : await request.text(),
    });
  } catch (e) {
    return new Response(JSON.stringify({ status_code: 502, status_message: "upstream error: " + (e && e.message) }), {
      status: 502,
      headers: { "Content-Type": "application/json" },
    });
  }

  // 记录被转发的剧集（只在 tv 详情 / tv 搜索时解析响应）
  const isTV = path === "/3/search/tv" || /^\/3\/tv\/\d+/.test(path);
  let passthrough = resp;
  if (isTV) {
    try {
      const clone = resp.clone();
      const data = await clone.json();
      await logShows(extractShows(data, path));
    } catch (e) {
      console.error("[log-parse] skip:", e && e.message);
    }
    passthrough = resp;
  }

  const newResp = new Response(passthrough.body, passthrough);
  const cors = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, HEAD, POST, OPTIONS",
    "Access-Control-Allow-Headers": "*",
    "Access-Control-Max-Age": "86400",
  };
  Object.entries(cors).forEach(([k, v]) => newResp.headers.set(k, v));
  return newResp;
}

export default {
  async fetch(request) {
    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, HEAD, POST, OPTIONS",
          "Access-Control-Allow-Headers": "*",
          "Access-Control-Max-Age": "86400",
        },
      });
    }
    return handleRequest(request);
  },
};
